/**
 * 端内绑定协议 —— 宿主路由与客户端面板的共享契约
 *
 * 类型与路径常量的唯一事实源：宿主（setup/bind-routes.ts）与浏览器
 * （client/bind-page.ts）各自 import，杜绝两端协议漂移。
 * 本模块必须保持纯类型 + 纯常量（零 node 依赖、零副作用）：
 * 客户端 tsdown 构建会将其内联进 bundle。
 */

/** 状态查询（绑定页轮询） */
export const BIND_STATE_PATH = '/qqbot/im-qqbot/bind';

/** 刷新二维码（绑定页按钮） */
export const BIND_REFRESH_PATH = '/qqbot/im-qqbot/bind/refresh';

/** 手动填写/编辑凭据（绑定页表单） */
export const BIND_MANUAL_PATH = '/qqbot/im-qqbot/bind/manual';

/** 解绑：移除已保存凭据，回到绑定流程 */
export const BIND_UNBIND_PATH = '/qqbot/im-qqbot/bind/unbind';

/** 配置读写（设置面板表单） */
export const BIND_CONFIG_PATH = '/qqbot/im-qqbot/config';

/** 插件更新检查与执行（设置面板「插件更新」页签） */
export const BIND_UPDATE_PATH = '/qqbot/im-qqbot/update';

/** NapCat（OneBot 11 实现）托管：状态查询 + 安装/启动/停止/刷新 */
export const BIND_NAPCAT_PATH = '/qqbot/im-qqbot/napcat';

/** NapCat 托管阶段（与 onebot/napcat.ts 的 NapcatPhase 同字面量） */
export type NapcatPhaseWire =
  | 'unsupported'
  | 'not_installed'
  | 'installing'
  | 'installed'
  | 'starting'
  | 'running'
  | 'login_required'
  | 'error';

/** NapCat 托管状态（HTTP 序列化形态） */
export interface NapcatStateWire {
  phase: NapcatPhaseWire;
  platform: string;
  installDir: string;
  qqPath?: string;
  launcher?: string;
  webuiUrl: string;
  httpUrl: string;
  loggedIn: boolean;
  uin?: string;
  progress?: number;
  message?: string;
}

/** 面板可触发的托管动作 */
export type NapcatAction = 'install' | 'start' | 'stop' | 'refresh';

/** 托管动作的统一响应 */
export interface NapcatActionResponse {
  ok: boolean;
  state: NapcatStateWire;
  message?: string;
  error?: string;
}

/** 线上协议（HTTP 路由序列化形态） */
export type BindStateWire =
  | { phase: 'starting' }
  | { phase: 'waiting'; url: string; qrSvg?: string; issuedAt: number }
  | { phase: 'saving' }
  | { phase: 'failed'; reason: string }
  | { phase: 'bound'; appId: string };

/** manual / unbind 操作的统一响应 */
export interface BindActionResponse {
  ok: boolean;
  message?: string;
  error?: string;
}

/** 安装方式（决定更新检查走 git 远端还是 npm registry） */
export type UpdateInstallKind = 'git' | 'npm' | 'local' | 'unknown';

/** 当前安装信息（GET /update 回显，也是检查/更新的输入） */
export interface UpdateInstallWire {
  packageName: string;
  kind: UpdateInstallKind;
  /** 当前加载的插件版本（package.json 的 version） */
  version: string;
  /** 已安装引用：git = commit，npm = 版本号，local = 依赖写法 */
  installed: string;
  /** profile package.json 里的依赖写法 */
  spec?: string;
  /** git 远端地址 */
  remote?: string;
  /** git 分支/标签（依赖写法 # 之后的内容） */
  ref?: string;
  /** 当前宿主是否支持一键更新（桌面版提供 pnpm 服务） */
  canUpdate: boolean;
  /** 无法一键更新时展示的手动命令 */
  command: string;
  /** 附加说明（不支持自更新的原因等） */
  message?: string;
}

/** 远端检查结果 */
export interface UpdateCheckWire {
  updateAvailable: boolean;
  /** 远端最新引用：git = commit，npm = 版本号 */
  latest: string;
  /** 检查时间（epoch ms） */
  checkedAt: number;
  message: string;
}

/** GET / POST(update) 的响应 */
export interface UpdateStateWire {
  ok?: boolean;
  install?: UpdateInstallWire;
  check?: UpdateCheckWire;
  message?: string;
  error?: string;
}

/** 发言档案采集统计（诊断「平台到底下发了什么」） */
export interface PersonaArchiveStatsWire {
  /** 已归档会话数（群 + 私聊） */
  chatCount: number;
  /** 已归档消息条数 */
  messageCount: number;
  /** 档案里的群友数（按 openid 去重） */
  memberCount: number;
  /** 最近一次成功写入的时间（毫秒） */
  lastArchivedAt?: number;
  /** 各入站事件类型的累计次数（如 GROUP_AT_MESSAGE_CREATE / C2C_MESSAGE_CREATE） */
  eventTypes: Record<string, number>;
  /**
   * 是否收到过 GROUP_MESSAGE_CREATE（群内全量消息）。
   *
   * 普通群机器人平台只下发 GROUP_AT_MESSAGE_CREATE（被 @ 的群消息），
   * 该字段为 false 就说明「群友未 @ 的发言」平台根本没推送。
   */
  groupFullMessages: boolean;
  /** 被跳过的入站消息计数（按原因） */
  skipped: Record<'bot' | 'slashCommand' | 'empty' | 'other', number>;
}
